import numpy as np
import json
import zlib
import base64

from pkbot.actions import ActionFold, ActionCall, ActionCheck, ActionRaise, ActionBid
from pkbot.states import GameInfo, PokerState
from pkbot.base import BaseBot
from pkbot.runner import parse_args, run_bot

COMPRESSED_WEIGHTS = \
""

class DeepCFRBot(BaseBot):
    def __init__(self):
        """
        Decompresses the embedded Base64 weights and reconstructs the NumPy network.
        This runs exactly once when the engine starts up.
        """
        print("Decompressing Deep CFR Strategy...")
        
        compressed_bytes = base64.b64decode(COMPRESSED_WEIGHTS)
        
        json_str = zlib.decompress(compressed_bytes).decode('utf-8')
        
        weights = json.loads(json_str)
            
        self.w1 = np.array(weights['fc1.weight'], dtype=np.float32).T
        self.b1 = np.array(weights['fc1.bias'], dtype=np.float32)
        
        self.w2 = np.array(weights['fc2.weight'], dtype=np.float32).T
        self.b2 = np.array(weights['fc2.bias'], dtype=np.float32)
        
        self.w3 = np.array(weights['fc3.weight'], dtype=np.float32).T
        self.b3 = np.array(weights['fc3.bias'], dtype=np.float32)
        
        self.w_out = np.array(weights['out.weight'], dtype=np.float32).T
        self.b_out = np.array(weights['out.bias'], dtype=np.float32)

        self.street_map = {'pre-flop': 0, 'flop': 3, 'auction': 3, 'turn': 4, 'river': 5}
        
        self.opp_auction_wins = 0
        self.my_auction_wins = 0
        
        print("Network loaded successfully.")

    def on_hand_start(self, game_info: GameInfo, current_state: PokerState) -> None:
        """Called at the beginning of every round."""
        pass

    def on_hand_end(self, game_info: GameInfo, current_state: PokerState) -> None:
        """Called when the round finishes."""
        if len(current_state.opp_revealed_cards) > 0:
            self.my_auction_wins += 1
        else:
            self.opp_auction_wins += 1

    def encode_cards(self, cards):
        """Converts list of card strings (e.g., 'As') to a 52-bit vector."""
        vec = np.zeros(52, dtype=np.float32)
        for card_str in cards:
            if not card_str: continue
            rank_idx = "23456789TJQKA".index(card_str[0].upper())
            suit_idx = "cdhs".index(card_str[1].lower())
            vec[rank_idx * 4 + suit_idx] = 1.0
        return vec

    def _encode_state_vector(self, current_state: PokerState):
        """Reconstructs the 164-dimensional tensor used during training."""
        hole_vec = self.encode_cards(current_state.my_hand)
        board_vec = self.encode_cards(current_state.board)
        revealed_vec = self.encode_cards(current_state.opp_revealed_cards)
        
        my_chips_norm = current_state.my_chips / 5000.0
        opp_chips_norm = current_state.opp_chips / 5000.0
        my_wager_norm = current_state.my_wager / 5000.0
        opp_wager_norm = current_state.opp_wager / 5000.0
        
        pot_norm = current_state.pot / 10000.0
        
        street_val = self.street_map.get(current_state.street.lower(), 0)
        street_norm = street_val / 5.0
        is_bb = 1.0 if current_state.is_bb else 0.0
        is_auction = 1.0 if current_state.street == 'auction' else 0.0
        
        numeric_features = np.array([my_chips_norm, opp_chips_norm, my_wager_norm, opp_wager_norm, pot_norm, street_norm, is_bb, is_auction], dtype=np.float32)
        
        return np.concatenate([hole_vec, board_vec, revealed_vec, numeric_features])

    def get_move(self, game_info: GameInfo, current_state: PokerState):
        """Where your strategy lives."""

        if current_state.street == 'auction' and game_info.round_num > 50:
            if (self.opp_auction_wins / game_info.round_num) < 0.15:
                return ActionBid(1)
        state_vector = self._encode_state_vector(current_state)
        
        x = np.dot(state_vector, self.w1) + self.b1
        x = np.where(x > 0, x, x * 0.01) # LeakyReLU
        
        x = np.dot(x, self.w2) + self.b2
        x = np.where(x > 0, x, x * 0.01) # LeakyReLU
        
        x = np.dot(x, self.w3) + self.b3
        x = np.where(x > 0, x, x * 0.01) # LeakyReLU
        
        logits = np.dot(x, self.w_out) + self.b_out
        
        mask = np.full(8, -np.inf)
        if current_state.street == 'auction':
            mask[0:4] = 0.0
        else:
            if current_state.can_act(ActionFold) or current_state.can_act(ActionCheck): 
                mask[4] = 0.0
            if current_state.can_act(ActionCall) or current_state.can_act(ActionCheck): 
                mask[5] = 0.0
            if current_state.can_act(ActionRaise): 
                mask[6:8] = 0.0
                
        valid_logits = logits + mask
        best_action_idx = np.argmax(valid_logits)
        
        return self._map_index_to_action(best_action_idx, current_state)

    def _map_index_to_action(self, idx, current_state: PokerState):
        """Translates the network's numerical decision into a legal API action."""
        if current_state.street == 'auction':
            max_bid = current_state.my_chips
            pot = current_state.pot
    
        # Override the 0-index prediction to use your 18-chip safety tax!
            if idx == 0: return ActionBid(min(max_bid, 18)) 
            if idx == 1: return ActionBid(min(max_bid, int(pot * 0.1)))
            if idx == 2: return ActionBid(min(max_bid, int(pot * 0.5)))
            if idx == 3: return ActionBid(max_bid)
            return ActionBid(min(max_bid, 18))
            
        if idx == 4:
            return ActionCheck() if current_state.can_act(ActionCheck) else ActionFold()
        if idx == 5:
            return ActionCheck() if current_state.can_act(ActionCheck) else ActionCall()
            
        if idx in [6, 7] and current_state.can_act(ActionRaise):
            min_raise, max_raise = current_state.raise_bounds
            pot = current_state.pot
            
            if idx == 6: return ActionRaise(min(max_raise, max(min_raise, int(pot))))
            if idx == 7: return ActionRaise(max_raise)
            
        return ActionCheck() if current_state.can_act(ActionCheck) else ActionFold()
    
if __name__ == "__main__":
    run_bot(DeepCFRBot(), parse_args())